INSERT INTO label_export_job (
    project_id, batch_id, export_format, status, param_json, result_url, created_by, updated_by
) VALUES (
    #{projectId}, #{batchId}, #{format}, #{status}, #{paramJson}, NULL, #{userId}, #{userId}
)

INSERT INTO label_delivery_record (
    project_id, export_job_id, dataset_version, export_format, asset_count,
    delivered_by, delivered_time, created_by, updated_by
) VALUES (
    #{projectId}, #{exportJobId}, #{datasetVersion}, #{format}, #{assetCount},
    #{userId}, NOW(), #{userId}, #{userId}
)

mapper.select:
SELECT en.id AS entryId, en.entry_no AS entryNo, en.entry_name AS entryName, asset.id AS assetId, asset.file_name AS fileName, asset.file_url AS fileUrl, JSON_UNQUOTE(JSON_EXTRACT(asset.meta_json, '$')) AS metaJson FROM label_data_entry en JOIN label_asset asset ON asset.entry_id = en.id AND asset.deleted = 0 AND asset.media_type = 'text' WHERE en.project_id = #{projectId} AND en.deleted = 0 AND (asset.frame_flag IS NULL OR asset.frame_flag <> 'invalid')
AND en.batch_id IN #{bid}
AND ORDER BY en.id

SELECT a.asset_id AS assetId, te.entity_key AS entityKey, te.class_id AS classId, c.label_name AS className, c.color AS color, te.start_offset AS startOffset, te.end_offset AS endOffset, te.entity_text AS entityText, te.sentence_index AS sentenceIndex FROM label_text_entity te JOIN label_annotation a ON a.id = te.annotation_id AND a.deleted = 0 JOIN label_asset asset ON asset.id = a.asset_id AND asset.deleted = 0 JOIN label_data_entry en ON en.id = asset.entry_id AND en.deleted = 0 LEFT JOIN label_text_class c ON c.id = te.class_id AND c.deleted = 0 WHERE en.project_id = #{projectId} AND te.deleted = 0
AND en.batch_id IN #{bid}
AND ORDER BY te.id

SELECT a.asset_id AS assetId, ts.level_type AS levelType, ts.sentence_index AS sentenceIndex, ts.class_id AS classId, c.label_name AS className, c.color AS color, ts.remark AS remark FROM label_text_sentiment ts JOIN label_annotation a ON a.id = ts.annotation_id AND a.deleted = 0 JOIN label_asset asset ON asset.id = a.asset_id AND asset.deleted = 0 JOIN label_data_entry en ON en.id = asset.entry_id AND en.deleted = 0 LEFT JOIN label_text_class c ON c.id = ts.class_id AND c.deleted = 0 WHERE en.project_id = #{projectId} AND ts.deleted = 0
AND en.batch_id IN #{bid}
AND ORDER BY ts.id

SELECT asset.id AS assetId, asset.media_type AS mediaType, asset.file_name AS fileName, asset.file_url AS fileUrl, asset.thumbnail_url AS thumbnailUrl, asset.file_size AS fileSize, asset.width AS width, asset.height AS height, asset.upload_id AS uploadId, asset.frame_flag AS frameFlag, asset.invalid_reason AS invalidReason, JSON_UNQUOTE(JSON_EXTRACT(asset.meta_json, '$')) AS metaJson FROM label_asset asset JOIN label_data_entry en ON en.id = asset.entry_id AND en.deleted = 0 WHERE asset.project_id = #{projectId} AND asset.deleted = 0
AND (asset.frame_flag IS NULL OR asset.frame_flag <> 'invalid')
AND en.batch_id = #{batchId}
AND en.batch_id IN #{bid}
AND ORDER BY asset.id

SELECT asset.id AS assetId, asset.upload_id AS uploadId, asset.file_name AS fileName, asset.frame_flag AS frameFlag, asset.invalid_reason AS invalidReason FROM label_asset asset JOIN label_data_entry en ON en.id = asset.entry_id AND en.deleted = 0 WHERE asset.project_id = #{projectId} AND asset.deleted = 0
AND en.batch_id = #{batchId}
AND en.batch_id IN #{bid}
AND ORDER BY asset.id

SELECT j.id AS jobId, j.job_no AS jobNo, j.data_type AS mediaType, asset.id AS assetId, asset.file_name AS fileName, a.id AS annotationId, a.version, a.status AS annotationStatus, ao.object_key AS objectKey, ao.object_type AS objectType, ao.class_id AS classId, c.label_name AS className, c.color, JSON_UNQUOTE(JSON_EXTRACT(ao.geometry_json, '$')) AS geometryJson, JSON_UNQUOTE(JSON_EXTRACT(ao.attr_json, '$')) AS attrJson FROM label_annotation a JOIN label_job j ON j.id = a.job_id AND j.deleted = 0 JOIN label_asset asset ON asset.id = a.asset_id AND asset.deleted = 0 JOIN label_data_entry en ON en.id = asset.entry_id AND en.deleted = 0 JOIN label_annotation_object ao ON ao.annotation_id = a.id AND ao.deleted = 0 LEFT JOIN label_class c ON c.id = ao.class_id WHERE asset.project_id = #{projectId} AND a.deleted = 0
AND (asset.frame_flag IS NULL OR asset.frame_flag <> 'invalid')
AND en.batch_id = #{batchId}
AND en.batch_id IN #{bid}
AND ORDER BY asset.id, j.id, ao.id
